const r = ($json && $json.output) ? $json.output : {};
const jobs = $('Get New Jobs').all();
const src = jobs[$itemIndex] || jobs[0];
const jobId = (src && src.json) ? src.json.id : null;
return {
  json: {
    job_id: jobId,
    approved: r.approved === true,
    score: (r.score !== undefined && r.score !== null) ? r.score : null,
    note: r.note || "",
    source: "groq",
  }
};

const body = $json || {};
let content = "";
try { content = body.choices[0].message.content || ""; } catch (e) { content = ""; }

let parsed = {};
let ok = false;
if (content) {
  try {
    let c = String(content).trim();
    const m = c.match(/\{[\s\S]*\}/);
    if (m) { c = m[0]; }
    parsed = JSON.parse(c);
    ok = true;
  } catch (e) { ok = false; }
}

const jobId = $('Build NVIDIA Prompt').item.json.job_id;

return {
  json: {
    job_id: jobId,
    approved: ok ? (parsed.approved === true) : false,
    score: (ok && parsed.score !== undefined && parsed.score !== null) ? parsed.score : null,
    note: ok
      ? ((parsed.note || "Backup review") + " [NVIDIA fallback]")
      : "Both reviewers unavailable (Groq failed, NVIDIA fallback could not parse) — saved for manual review.",
    source: "nvidia",
  }
};

const jobs = $('Get New Jobs').all();
const scored = $('Score & Draft').all();
const reviews = $input.all();
const candidateName = $('Candidate Profile').first().json.candidate_name;
const client = $('Client Input').first().json || {};
const jobType = client.job_type || 'full-time';
const threshold = String(jobType).toLowerCase().indexOf('intern') !== -1 ? 35 : 50;
const clientEmail = client.client_email || "";
const cvUrl = client.cv_url || "";

const reviewsById = {};
for (const it of reviews) {
  const rv = (it && it.json) ? it.json : {};
  if (rv.job_id !== undefined && rv.job_id !== null) {
    reviewsById[String(rv.job_id)] = rv;
  }
}

const out = [];
for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i].json || {};
  const s = (scored[i] && scored[i].json && scored[i].json.output) ? scored[i].json.output : {};
  const rv = reviewsById[String(job.id)] || {};
  const hasReview = Object.keys(rv).length > 0;
  const coverLetter = s.cover_letter || "";

  out.push({
    json: {
      id: job.id,
      job_title: job.job_title,
      company: job.company,
      location: job.location,
      job_description: job.job_description,
      job_url: job.job_url,
      contact_email: job.contact_email || "",
      candidate_name: candidateName,
      client_name: client.client_name || candidateName,
      client_email: clientEmail,
      cv_url: cvUrl,
      job_type: jobType,
      fit_threshold: threshold,
      fit_score: (s.fit_score !== undefined && s.fit_score !== null) ? s.fit_score : null,
      fit_reason: s.fit_reason || "",
      cover_letter: coverLetter,
      cover_letter_html: coverLetter.split("\n").join("<br>"),
      approved: hasReview ? (rv.approved === true) : false,
      review_score: hasReview ? ((rv.score !== undefined && rv.score !== null) ? rv.score : null) : null,
      review_note: hasReview ? (rv.note || "") : "Second-opinion reviewer unavailable — saved for manual review.",
      review_source: hasReview ? (rv.source || "groq") : "none",
    },
    pairedItem: { item: i },
  });
}
return out;

const items = $input.all();
const rows = [];
for (const it of items) {
  const r = it.json || {};
  if (r.job_title || r.company) { rows.push(r); }
}
const total = rows.length;
let appliedCount = 0;
let reviewedCount = 0;
let errorCount = 0;
const lines = [];
for (const r of rows) {
  const status = r.status || "processed";
  if (status === "applied") { appliedCount++; } else { reviewedCount++; }
  if (r.fit_score === null || r.fit_score === undefined) { errorCount++; }
  const score = (r.fit_score === 0 || r.fit_score) ? r.fit_score : "N/A";
  const reason = r.fit_reason || "";
  lines.push("• " + (r.job_title || "Untitled") + " @ " + (r.company || "Unknown") + " — fit " + score + " — " + status);
  if (reason) { lines.push("    " + reason); }
}
const client = $('Client Input').first().json || {};
const clientsProcessed = 1;
const date = $now.toFormat("yyyy-LL-dd");
const nextSteps = reviewedCount > 0
  ? (reviewedCount + " application(s) saved for manual review — check the job_applications table.")
  : "No pending reviews. System will continue on the next scheduled run.";
const subject = "Delivery Report " + date + ": " + appliedCount + " sent / " + total + " processed";
const bodyLines = [
  "Delivery Report — " + date,
  "Client: " + (client.client_name || "N/A") + " (" + (client.client_email || "N/A") + ") — " + (client.job_type || "N/A"),
  "Target volume: " + (client.target_volume !== undefined ? client.target_volume : "N/A"),
  "",
  "Clients processed: " + clientsProcessed,
  "Applications sent: " + appliedCount,
  "Errors logged: " + errorCount,
  "Saved for review: " + reviewedCount,
  "",
  "Next steps:",
  nextSteps,
  "",
  "Details:",
].concat(lines);
const body = bodyLines.join("\n");
const htmlBody = bodyLines.join("<br>");
return [{ json: { subject, body, htmlBody, total, applications_sent: appliedCount, clients_processed: clientsProcessed, errors_logged: errorCount, saved_for_review: reviewedCount, next_steps: nextSteps } }];

const body = ($('Add Job Webhook').item.json && $('Add Job Webhook').item.json.body) ? $('Add Job Webhook').item.json.body : {};

return {
  json: {
    company: body.company || "",
    email: body.email || "",
    cv_url: body.cv_url || "",
    job_type: body.job_type || "",
    industry: body.industry_preference || "",
    target_volume: (body.target_volume !== undefined && body.target_volume !== null && body.target_volume !== "") ? Number(body.target_volume) : null,
    status: "new",
    date_added: new Date().toISOString(),
  }
};

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const ACTIVE = ['new','pending','sent'];
const active = rows.filter(r => ACTIVE.includes(String(r.status || '').toLowerCase().trim()));
const mapped = $('Map Job Fields').first().json;
return [{ json: Object.assign({}, mapped, { is_duplicate: active.length > 0, duplicate_count: active.length }) }];

const r = $json;
const score = (r.fit_score === 0 || r.fit_score) ? r.fit_score : 'N/A';
const threshold = (r.fit_threshold === 0 || r.fit_threshold) ? r.fit_threshold : 'N/A';
const reason = r.fit_reason || 'No detailed reasoning available.';
const reviewNote = r.review_note || '';
const reviewScore = (r.review_score === 0 || r.review_score) ? r.review_score : null;
const html = [
  '<h2>Your CV Match Report</h2>',
  '<p>Hello ' + (r.client_name || 'there') + ',</p>',
  '<p>Here is how your CV matches against <strong>' + (r.job_title || 'the role') + '</strong>' + (r.company ? ' at <strong>' + r.company + '</strong>' : '') + '.</p>',
  '<h3>Match Score: ' + score + ' / 100</h3>',
  '<p><em>Suggested threshold for this job type: ' + threshold + '</em></p>',
  '<h3>Assessment</h3>',
  '<p>' + String(reason).split('\n').join('<br>') + '</p>',
  (reviewScore !== null ? ('<h3>Second Opinion: ' + reviewScore + ' / 100</h3><p>' + String(reviewNote).split('\n').join('<br>') + '</p>') : ''),
  '<hr><p style="color:#888;font-size:12px">This is an automated CV match report. No application was submitted.</p>'
].join('');
return { json: Object.assign({}, r, { audit_report_html: html, status: 'audit_completed' }) };

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const body = ($('Add Job Webhook').first().json.body) || {};
const clientEmail = body.email || body.client_email || '';
const now = Date.now();
const windowMs = 60 * 60 * 1000;
const recent = rows.filter(r => {
  if (!r.submitted_at) return false;
  const t = new Date(r.submitted_at).getTime();
  return !isNaN(t) && (now - t) <= windowMs;
});
const exceeded = recent.length > 5;
return [{ json: { client_email: clientEmail, recent_count: recent.length, exceeded, submitted_at: new Date().toISOString() } }];

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const r = rows[0] || {};
let stale = false;
if (r.is_locked === true && r.locked_at) {
  const t = new Date(r.locked_at).getTime();
  if (!isNaN(t) && (Date.now() - t) > 30*60*1000) stale = true;
}
return [{ json: { is_stale: stale, is_locked: r.is_locked === true, locked_at: r.locked_at || null } }];

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const out = rows.map(r => ({ job_title: r.job_title || '', company: r.company || '', status: r.status || '' }));
return [{ json: { client_id: ($('Client Status Webhook').first().json.query || {}).client_id || '', count: out.length, applications: out } }];
